arguments.file_text:
@using sv_50bd3553fb7f4191bf59652c17dd8ae9.Models

<div class="personal-info-step">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" @bind="FullName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" @bind="Email" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="validation-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" @bind="Phone" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" class="form-control" @bind="Address" @bind:event="oninput" rows="2"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_validationMessage))
    {
        <div class="validation-summary">@_validationMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string _validationMessage = "";
    private string _emailError = "";
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationMessage = "";
        _emailError = "";

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            _isValidating = true;
            StateHasChanged();
            var isValid = await ValidateEmail(Email);
            _isValidating = false;

            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@using sv_50bd3553fb7f4191bf59652c17dd8ae9.Models

<div class="work-entry-form">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button class="btn btn-sm btn-outline-danger" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company *</label>
            <input type="text" class="form-control" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")); NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description" @oninput="e => { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync(Index);
    }
}

@using sv_50bd3553fb7f4191bf59652c17dd8ae9.Models

<div class="work-history-step">
    <h3>Work History</h3>

    @for (int i = 0; i < _entries.Count; i++)
    {
        var entry = _entries[i];
        var idx = i;
        <WorkEntryForm Index="idx"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(_entries.Count > 1)"
                       OnRemove="RemoveEntry"
                       OnChanged="UpdateEntry" />
    }

    <button class="btn btn-outline-secondary btn-add" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationMessage))
    {
        <div class="validation-summary">@_validationMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel>? Entries { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }

    private List<WorkEntryModel> _entries = new();
    private string _validationMessage = "";

    protected override void OnParametersSet()
    {
        if (Entries is not null && Entries.Count > 0)
        {
            _entries = Entries.Select(e => e with { }).ToList();
        }
        else if (_entries.Count == 0)
        {
            _entries.Add(new WorkEntryModel());
        }
    }

    private void AddEntry()
    {
        _entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (_entries.Count > 1 && index < _entries.Count)
        {
            _entries.RemoveAt(index);
        }
    }

    private void UpdateEntry((int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description) data)
    {
        if (data.Index < _entries.Count)
        {
            _entries[data.Index] = new WorkEntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        _validationMessage = "";
        foreach (var entry in _entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationMessage = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(_entries);
    }

