@code {
    [Parameter] public List<ReferenceModel>? References { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }

    private List<ReferenceModel> _references = new();
    private string _validationMessage = "";

    protected override void OnParametersSet()
    {
        if (References is not null && References.Count > 0)
        {
            _references = References.Select(r => r with { }).ToList();
        }
        else if (_references.Count == 0)
        {
            _references.Add(new ReferenceModel());
            _references.Add(new ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
        {
            _references.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2 && index < _references.Count)
        {
            _references.RemoveAt(index);
        }
    }

    private void UpdateReference((int Index, string Name, string Relationship, string Email, string Phone) data)
    {
        if (data.Index < _references.Count)
        {
            _references[data.Index] = new ReferenceModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        _validationMessage = "";
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationMessage = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(_references);
    }

