@using sv_50bd3553fb7f4191bf59652c17dd8ae9.Models
@using static sv_50bd3553fb7f4191bf59652c17dd8ae9.Components.Pages.Apply.WorkHistoryStep
@using static sv_50bd3553fb7f4191bf59652c17dd8ae9.Components.Pages.Apply.ReferencesStep

<div class="review-step">
    <h3>Review & Submit</h3>
    <p class="step-description">Please review your application before submitting.</p>

    @if (_submitted)
    {
        <div class="submission-confirmation">
            <div class="success-icon">&#10003;</div>
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>We'll be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditSection(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal?.FullName</dd>
                <dt>Email</dt><dd>@Personal?.Email</dd>
                <dt>Phone</dt><dd>@Personal?.Phone</dd>
                <dt>Address</dt><dd>@Personal?.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditSection(1)">Edit</button>
            </div>
            @if (WorkEntries is not null)
            {
                @foreach (var entry in WorkEntries)
                {
                    <div class="work-review-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                        <div class="date-range">
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </div>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="entry-description">@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>References</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditSection(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="reference-review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)
                        <div>@r.Email &bull; @r.Phone</div>
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>Cover Letter</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditSection(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
        </div>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="validation-summary">@_errorMessage</div>
        }

        <div class="step-buttons">
            <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @if (_isSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public List<WorkEntryModel>? WorkEntries { get; set; }
    [Parameter] public List<ReferenceModel>? References { get; set; }
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string _errorMessage = "";

    private async Task EditSection(int step)
    {
        await OnEditSection.InvokeAsync(step);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        _isSubmitting = true;
        _errorMessage = "";
        StateHasChanged();

        try
        {
            _applicationId = await OnSubmit();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

