    background: #5c636a;
}

::deep .btn-success {
    background: #198754;
    color: #fff;
}

::deep .btn-success:hover {
    background: #157347;
}

::deep .btn-success:disabled {
    background: #5cb888;
    cursor: not-allowed;
}

::deep .btn-lg {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

::deep .btn-outline-secondary {
    background: transparent;
    border: 1px dashed #6c757d;
    color: #6c757d;
    padding: 0.5rem 1rem;
