@page "/apply"
@rendermode InteractiveServer
@using sv_50bd3553fb7f4191bf59652c17dd8ae9.Models
@using sv_50bd3553fb7f4191bf59652c17dd8ae9.Services
@using static sv_50bd3553fb7f4191bf59652c17dd8ae9.Components.Pages.Apply.WorkHistoryStep
@using static sv_50bd3553fb7f4191bf59652c17dd8ae9.Components.Pages.Apply.ReferencesStep
@inject IApplicationService ApplicationService

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnBack="() => _currentStep = 0"
                                 OnNext="HandleWorkHistoryNext" />
                break;
            case 2:
                <ReferencesStep References="_references"
                                OnBack="() => _currentStep = 1"
                                OnNext="HandleReferencesNext" />
                break;
            case 3:
                <CoverLetterStep CoverLetterText="@_coverLetter"
                                 OnBack="() => _currentStep = 2"
                                 OnNext="HandleCoverLetterNext" />
                break;
            case 4:
                <ReviewStep Personal="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            OnBack="() => _currentStep = 3"
                            OnEditSection="GoToStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private PersonalInfo? _personalInfo;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new();

    // Step 3 state
    private List<ReferenceModel> _references = new();

    // Step 4 state
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        _personalInfo = info;
        _fullName = info.FullName;
        _email = info.Email;
        _phone = info.Phone;
        _address = info.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description
            )).ToList()
        );

        var references = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)
        ).ToList();

        var application = new JobApplication(_personalInfo!, workHistory, references, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

