@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)> OnChanged { get; set; }

    private string StartDateString => StartDate.ToString("yyyy-MM-dd");
    private string EndDateString => EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void OnCompanyInput(ChangeEventArgs e) { Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }
    private void OnTitleInput(ChangeEventArgs e) { Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }
    private void OnDescriptionInput(ChangeEventArgs e) { Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }

    private void OnStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            StartDate = date;
        NotifyChanged();
    }

    private void OnEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnCurrentChange(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync(Index);
    }
}

